    expect(run.state.rubbings.map((rubbing) => [rubbing.id, rubbing.location])).toEqual(before.rubbings);
    expect([run.gold("a"), run.gold("b")]).toEqual(before.gold);
    expect(run.do(reportDuelResult, { duelId: "nope", tick: run.now, outcome: "draw" }).rejection).toBe("unknown-duel");
    expect(run.do(reportDuelResult, { duelId: "d2", tick: run.now, outcome: "win", winner: "a" }).rejection).toBe("already-resolved");
  });

  it("rounds gold down, caps it at 50 and never takes more than the loser has", () => {
    const cases: [number, number][] = [[57, 11], [4, 0], [400, 50], [0, 0]];
    cases.forEach(([loserGold, taken], index) => {
      let state = createLedger({ preset: "slice", seed: index, sites: sites("slice") });
      state = addPlayer(state, { playerId: "w", tick: 0 }).state;
      state = addPlayer(state, { playerId: "l", tick: 0, gold: loserGold }).state;
      state = reserveDuel(state, { duelId: "d", players: ["w", "l"], tick: 1 }).state;
      state = reportDuelResult(state, { duelId: "d", tick: 2, outcome: "win", winner: "w" }).state;
      assertLedger(state);
      expect(findPlayer(state, "l")!.gold).toBe(loserGold - taken);
      expect(findPlayer(state, "w")!.gold).toBe(50 + taken);
    });
  });

      expect(run.where("moon-1")).toEqual(player(order[0]));
      expect(heldTypes(run.state, order[1])).toEqual([]);
    }
  });
});

describe("economy: minted gold (§11)", () => {
  it("grants ruin gold once per player per ruin; a repeat is refused and changes nothing", () => {
    const run = new Run("slice", ["a", "b"]);
    const issued = run.state.goldIssued;
    const first = run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-3", tick: run.now });
    expect(first).toMatchObject({ ok: true, grant: { reason: "ruin", sourceKey: "ruin-3", playerId: "a", amount: 40 } });
    expect(run.gold("a")).toBe(90);
    const repeat = run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-3", tick: ++run.now });
    expect(repeat).toMatchObject({ ok: false, rejection: "duplicate", grant: first.grant });
    expect(run.gold("a")).toBe(90);
    expect(run.do(grantGold, { playerId: "b", reason: "ruin", sourceKey: "ruin-3", tick: run.now }).ok).toBe(true);
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-4", tick: run.now }).ok).toBe(true);
    expect(run.gold("a")).toBe(130);
    expect(run.gold("b")).toBe(90);
    expect(run.state.goldIssued).toBe(issued + 3 * 40);
    run.expectGoldAccounted();
  });

  it("grants a supply cache once per match, to whoever claims it first", () => {
    const run = new Run("slice", ["a", "b"]);
    expect(run.do(grantGold, { playerId: "b", reason: "supply-cache", sourceKey: "supply-1", tick: run.now }).grant?.amount).toBe(25);
    const late = run.do(grantGold, { playerId: "a", reason: "supply-cache", sourceKey: "supply-1", tick: run.now });
    expect(late).toMatchObject({ ok: false, rejection: "already-claimed", grant: { playerId: "b" } });
    expect(run.do(grantGold, { playerId: "b", reason: "supply-cache", sourceKey: "supply-1", tick: run.now }).rejection).toBe("duplicate");
    // A ruin and a supply cache never share a key.
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "supply-1", tick: run.now }).ok).toBe(true);
    expect([run.gold("a"), run.gold("b"), run.state.goldIssued]).toEqual([90, 75, 165]);
    run.expectGoldAccounted();
  });

  it("takes the amounts from the rules, never from the caller, and pays nobody who left", () => {
    const run = new Run("slice", ["a", "b"], 11, { ...objectiveRules, ruinGold: 7, supplyCacheGold: 3 });
    const forged = { playerId: "a", reason: "ruin", sourceKey: "ruin-1", tick: run.now, amount: 1000 } as const;
    expect(run.do(grantGold, forged).grant?.amount).toBe(7);
    expect(run.do(grantGold, { playerId: "a", reason: "supply-cache", sourceKey: "s", tick: run.now }).grant?.amount).toBe(3);
    expect(run.gold("a")).toBe(60);
    expect(run.do(quitPlayer, { playerId: "b", tick: run.now, position: { x: 0, y: 0 } }).ok).toBe(true);
    expect(run.do(grantGold, { playerId: "b", reason: "ruin", sourceKey: "ruin-1", tick: run.now }).rejection).toBe("player-left");
    expect(run.do(grantGold, { playerId: "c", reason: "ruin", sourceKey: "ruin-1", tick: run.now }).rejection).toBe("unknown-player");
    const bogus = { playerId: "a", reason: "kill", sourceKey: "ruin-9", tick: run.now } as unknown as Parameters<typeof grantGold>[1];
    expect(run.do(grantGold, bogus).rejection).toBe("invalid-request");
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "", tick: run.now }).rejection).toBe("invalid-request");
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-9", tick: run.now - 1 }).rejection).toBe("stale-tick");
    run.expectGoldAccounted();
  });
});

describe("economy: purchases (§11, §16)", () => {
  it("charges the rules' prices and spends the gold rather than moving it", () => {
    const run = new Run("slice", ["a", "b"]);
    const rumor = run.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: run.now });
    expect(rumor).toMatchObject({ ok: true, replayed: false, purchase: { item: "rumor", price: 25, goldAfter: 25, tonicsAfter: 0 } });
    run.expectGoldAccounted();
    const tonic = run.do(purchase, { requestId: "r2", playerId: "b", item: "tonic", tick: run.now });
    expect(tonic).toMatchObject({ ok: true, purchase: { item: "tonic", price: 30, goldAfter: 20, tonicsAfter: 1 } });
    expect([run.gold("a"), run.gold("b"), run.tonics("b"), run.state.goldSpent, run.state.goldIssued]).toEqual([25, 20, 1, 55, 100]);
    run.expectGoldAccounted();
    const priced = new Run("slice", ["a"], 11, { ...objectiveRules, rumorPrice: 9, tonicPrice: 11 });
    expect(priced.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: 1 }).purchase?.price).toBe(9);
    expect(priced.do(purchase, { requestId: "r2", playerId: "a", item: "tonic", tick: 1 }).purchase?.price).toBe(11);
    expect(priced.gold("a")).toBe(30);
    priced.expectGoldAccounted();
  });

  it("refuses when gold is short, in a duel, disconnected, gone, or for a third tonic", () => {
    const run = new Run("slice", ["a", "b", "c"]);
    const buy = (requestId: string, playerId: string, item: "rumor" | "tonic") =>
      run.do(purchase, { requestId, playerId, item, tick: run.now });
    expect(buy("r1", "a", "tonic").ok).toBe(true);
    expect(buy("r2", "a", "rumor").rejection).toBe("insufficient-gold");
    expect(run.gold("a")).toBe(20);
    run.expectGoldAccounted();

    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-1", tick: run.now }).ok).toBe(true);
    expect(buy("r3", "a", "tonic").ok).toBe(true);
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-2", tick: run.now }).ok).toBe(true);
    expect(run.gold("a")).toBe(70);
    expect(buy("r4", "a", "tonic").rejection).toBe("tonic-limit");
    expect([run.gold("a"), run.tonics("a")]).toEqual([70, 2]);
    expect(buy("r4", "a", "rumor").ok).toBe(true);
    run.expectGoldAccounted();

    expect(run.do(reserveDuel, { duelId: "d1", players: ["b", "c"], tick: ++run.now }).ok).toBe(true);
    expect(buy("r5", "b", "rumor").rejection).toBe("player-in-duel");
    expect(run.do(reportDuelResult, { duelId: "d1", tick: ++run.now, outcome: "draw" }).ok).toBe(true);
    expect(buy("r5", "b", "rumor").ok).toBe(true);
    run.expectGoldAccounted();

    expect(run.do(disconnectPlayer, { playerId: "c", tick: run.now }).ok).toBe(true);
    expect(buy("r6", "c", "rumor").rejection).toBe("player-disconnected");
    expect(run.do(quitPlayer, { playerId: "b", tick: run.now, position: { x: 0, y: 0 } }).ok).toBe(true);
    expect(buy("r7", "b", "rumor").rejection).toBe("player-left");
    expect(buy("r8", "ghost", "rumor").rejection).toBe("unknown-player");
    expect(buy("", "a", "rumor").rejection).toBe("invalid-request");
    expect(run.do(purchase, { requestId: "r9", playerId: "a", item: "scroll" as "rumor", tick: run.now }).rejection).toBe("invalid-request");
    expect(run.do(purchase, { requestId: "r9", playerId: "a", item: "rumor", tick: run.now - 1 }).rejection).toBe("stale-tick");
    run.expectGoldAccounted();
  });

  it("answers a repeated request id with the original purchase, never charging twice, even after other operations", () => {
    const run = new Run("slice", ["a", "b"]);
    const original = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now });
    expect(original.ok).toBe(true);
    const settled = run.state;
    const retry = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now });
    expect(retry).toEqual({ ...original, replayed: true });
    expect(run.state).toBe(settled);

    // Other operations in between: a grant, another purchase, a used tonic and a lost duel.
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-1", tick: ++run.now }).ok).toBe(true);
    expect(run.do(purchase, { requestId: "r2", playerId: "a", item: "rumor", tick: run.now }).ok).toBe(true);
    expect(run.do(useTonic, { playerId: "a", tick: run.now, atSea: true, grappled: false }).ok).toBe(true);
    run.duel("d1", "a", "b", "b");
    const [gold, tonics, spent] = [run.gold("a"), run.tonics("a"), run.state.goldSpent];

    const before = run.state;
    const late = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: ++run.now });
    expect(late).toEqual({ ...original, replayed: true });
    expect(run.state).toBe(before);
    // A retry carrying an old tick still finds its purchase rather than failing as stale.
    expect(run.do(purchase, { requestId: "r2", playerId: "a", item: "rumor", tick: 0 }).replayed).toBe(true);
    expect([run.gold("a"), run.tonics("a"), run.state.goldSpent]).toEqual([gold, tonics, spent]);
    // The same id reused by another player or for another item is refused, not replayed.
    expect(run.do(purchase, { requestId: "r1", playerId: "b", item: "tonic", tick: run.now }).rejection).toBe("duplicate");
    expect(run.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: run.now }).rejection).toBe("duplicate");
    expect(run.state.purchases.map((record) => record.requestId)).toEqual(["r1", "r2"]);
    run.expectGoldAccounted();
  });
});

describe("economy: sail tonics (§11)", () => {
  /** A run where `a` carries two tonics and `b` one. */
  function stocked(): Run {
    const run = new Run("slice", ["a", "b"]);
    run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "ruin-1", tick: run.now });
    for (const [requestId, playerId] of [["r1", "a"], ["r2", "a"], ["r3", "b"]] as const) {
      expect(run.do(purchase, { requestId, playerId, item: "tonic", tick: run.now }).ok).toBe(true);
    }
    return run;
  }

  it("is active for exactly 12 seconds: from its activation tick to 239 ticks later", () => {
    const run = stocked();
    const start = (run.now = 100);
    expect(run.do(useTonic, { playerId: "a", tick: start, atSea: true, grappled: false }).player?.tonicEffect).toEqual({
      startTick: 100,
      endTick: 340,
    });
    expect(objectiveRules.tonicTicks).toBe(240);
    expect(run.tonics("a")).toBe(1);
    expect(activeTonic(run.state, "a", start - 1)).toBe(false);
    expect(activeTonic(run.state, "a", start)).toBe(true);
    expect(activeTonic(run.state, "a", start + 239)).toBe(true);
    expect(activeTonic(run.state, "a", start + 240)).toBe(false);
    expect(activeTonic(run.state, "b", start)).toBe(false);
    expect(activeTonic(run.state, "ghost", start)).toBe(false);
  });

  it("allows one active at a time, and another once it ends", () => {
    const run = stocked();
    expect(run.do(useTonic, { playerId: "a", tick: 10, atSea: true, grappled: false }).ok).toBe(true);
    expect(run.do(useTonic, { playerId: "a", tick: 10, atSea: true, grappled: false }).rejection).toBe("tonic-active");
    expect(run.do(useTonic, { playerId: "a", tick: 249, atSea: true, grappled: false }).rejection).toBe("tonic-active");
    expect(run.tonics("a")).toBe(1);
    expect(run.do(useTonic, { playerId: "a", tick: 250, atSea: true, grappled: false }).ok).toBe(true);
    expect(run.tonics("a")).toBe(0);
    expect(run.do(useTonic, { playerId: "a", tick: 600, atSea: true, grappled: false }).rejection).toBe("no-tonic");
  });

  it("is refused in a duel, off the sea, while grappled or disconnected", () => {
    const run = stocked();
    const use = (atSea: boolean, grappled: boolean, playerId = "a") => run.do(useTonic, { playerId, tick: run.now, atSea, grappled });
    expect(use(false, false).rejection).toBe("not-at-sea");
    expect(use(true, true).rejection).toBe("grappled");
    expect(run.do(reserveDuel, { duelId: "d1", players: ["a", "b"], tick: ++run.now }).ok).toBe(true);
    expect(use(true, false).rejection).toBe("player-in-duel");
    expect(run.do(reportDuelResult, { duelId: "d1", tick: ++run.now, outcome: "draw" }).ok).toBe(true);
    expect(run.do(disconnectPlayer, { playerId: "b", tick: run.now }).ok).toBe(true);
    expect(use(true, false, "b").rejection).toBe("player-disconnected");
    expect(run.do(useTonic, { playerId: "a", tick: run.now, atSea: "yes" as unknown as boolean, grappled: false }).rejection).toBe(
      "invalid-request",
    );
    expect(run.tonics("a")).toBe(2);
    expect(use(true, false).ok).toBe(true);
  });

  it("keeps the tonics after a lost duel and drops them, active one included, on leaving", () => {
    const run = stocked();
    const gold = run.gold("a");
    const lost = run.duel("d1", "a", "b", "b");
    expect(lost.duel?.phase).toBe("settled");
    expect(run.gold("a")).toBeLessThan(gold);
    expect(run.tonics("a")).toBe(2);
    expect(run.do(useTonic, { playerId: "a", tick: run.now, atSea: true, grappled: false }).ok).toBe(true);
    expect(run.do(quitPlayer, { playerId: "a", tick: ++run.now, position: { x: 0, y: 0 } }).ok).toBe(true);
    expect(run.tonics("a")).toBe(0);
    expect(findPlayer(run.state, "a")!.tonicEffect).toBeNull();
    expect(activeTonic(run.state, "a", run.now)).toBe(false);
    expect(run.do(useTonic, { playerId: "a", tick: run.now, atSea: true, grappled: false }).rejection).toBe("player-left");
    run.do(disconnectPlayer, { playerId: "b", tick: run.now });
    expect(run.do(expireReservation, { playerId: "b", tick: run.now + 1200, position: { x: 0, y: 0 } }).ok).toBe(true);
    expect(run.tonics("b")).toBe(0);
    run.expectGoldAccounted();
  });
});

describe("requests", () => {
  it("refuses stale and malformed requests without changing anything", () => {
    const run = new Run("slice", ["a", "b"]);
    run.do(advanceLedger, { tick: 50 });
    expect(run.do(addPlayer, { playerId: "c", tick: 49 }).rejection).toBe("stale-tick");
    expect(run.do(advanceLedger, { tick: 10 }).rejection).toBe("stale-tick");
    expect(run.do(addPlayer, { playerId: "c", tick: 50.5 }).rejection).toBe("invalid-request");
    expect(run.do(addPlayer, { playerId: "", tick: 50 }).rejection).toBe("invalid-request");
    expect(run.do(addPlayer, { playerId: "c", tick: 50, gold: -1 }).rejection).toBe("invalid-request");
    expect(run.do(quitPlayer, { playerId: "a", tick: 50, position: { x: 0.5, y: 0 } }).rejection).toBe("invalid-request");
    expect(run.do(unlockSource, { sourceId: run.state.sources[0]!.id, tick: 50 }).rejection).toBe("duplicate");
    expect(run.do(unlockSource, { sourceId: "nope", tick: 50 }).rejection).toBe("unknown-source");
  });

  it("never writes into its input and hashes equal states equally", () => {
    const a = new Run("alpha", ["a", "b"]);
    const b = new Run("alpha", ["a", "b"]);
    for (const run of [a, b]) {
      run.collect("a", "storm-2");
      run.duel("d1", "b", "a", "b");
      run.do(advanceLedger, { tick: run.now + 100 });
    }
    expect(hashState(a.state)).toBe(hashState(b.state));
    expect(Object.isFrozen(a.state.rubbings[0])).toBe(true);
  });
});

