    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "supply-1", tick: run.now }).rejection).toBe("unknown-source");
    expect(run.do(grantGold, { playerId: "a", reason: "supply-cache", sourceKey: "0", tick: run.now }).rejection).toBe("unknown-source");
    expect(run.do(grantGold, { playerId: "a", reason: "supply-cache", sourceKey: "supply-2", tick: run.now }).ok).toBe(true);
