    const bogus = { playerId: "a", reason: "kill", sourceKey: "2", tick: run.now } as unknown as Parameters<typeof grantGold>[1];
    expect(run.do(grantGold, bogus).rejection).toBe("invalid-request");
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "", tick: run.now }).rejection).toBe("invalid-request");
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "2", tick: run.now - 1 }).rejection).toBe("stale-tick");
    run.expectGoldAccounted();
  });

  it("only mints for keys the ledger knows: an island's ruin, or a supply cache given at creation", () => {
