    // The ruin key is exactly String(island), as the ruins module keys its ruins; the slice has islands 0 to 3.
    for (const key of ["4", "01", " 1", "1.0", "-0", "ruin-1", "island-1"]) expect(grant("ruin", key).rejection).toBe("unknown-source");
