    expect(hashState(other)).not.toBe(hashState(createLedger({ preset: "slice", seed: 11, sites: sites("slice"), supplyCaches: SUPPLY_CACHES })));
    expect(() => createLedger({ preset: "slice", seed: 11, sites: sites("slice"), supplyCaches: ["s", "s"] })).toThrow(/supply caches/);
