    const rumor = run.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: run.now });
    expect(rumor).toMatchObject({ ok: true, replayed: false, purchase: { item: "rumor", price: 25, goldAfter: 25, tonicsAfter: 0 } });
    run.expectGoldAccounted();
    const tonic = run.do(purchase, { requestId: "r2", playerId: "b", item: "tonic", tick: run.now });
    expect(tonic).toMatchObject({ ok: true, purchase: { item: "tonic", price: 30, goldAfter: 20, tonicsAfter: 1 } });
    expect([run.gold("a"), run.gold("b"), run.tonics("b"), run.state.goldSpent, run.state.goldIssued]).toEqual([25, 20, 1, 55, 100]);
    run.expectGoldAccounted();
    const priced = new Run("slice", ["a"], 11, { ...objectiveRules, rumorPrice: 9, tonicPrice: 11 });
    expect(priced.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: 1 }).purchase?.price).toBe(9);
    expect(priced.do(purchase, { requestId: "r2", playerId: "a", item: "tonic", tick: 1 }).purchase?.price).toBe(11);
    expect(priced.gold("a")).toBe(30);
    priced.expectGoldAccounted();
  });

  it("refuses when gold is short, in a duel, disconnected, gone, or for a third tonic", () => {
    const run = new Run("slice", ["a", "b", "c"]);
    const buy = (requestId: string, playerId: string, item: "rumor" | "tonic") =>
      run.do(purchase, { requestId, playerId, item, tick: run.now });
    expect(buy("r1", "a", "tonic").ok).toBe(true);
    expect(buy("r2", "a", "rumor").rejection).toBe("insufficient-gold");
    expect(run.gold("a")).toBe(20);
    run.expectGoldAccounted();

    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "1", tick: run.now }).ok).toBe(true);
    expect(buy("r3", "a", "tonic").ok).toBe(true);
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "2", tick: run.now }).ok).toBe(true);
    expect(run.gold("a")).toBe(70);
    expect(buy("r4", "a", "tonic").rejection).toBe("tonic-limit");
    expect([run.gold("a"), run.tonics("a")]).toEqual([70, 2]);
    expect(buy("r5", "a", "rumor").ok).toBe(true);
    run.expectGoldAccounted();

    expect(run.do(reserveDuel, { duelId: "d1", players: ["b", "c"], tick: ++run.now }).ok).toBe(true);
    expect(buy("r6", "b", "rumor").rejection).toBe("player-in-duel");
    expect(run.do(reportDuelResult, { duelId: "d1", tick: ++run.now, outcome: "draw" }).ok).toBe(true);
    expect(buy("r7", "b", "rumor").ok).toBe(true);
    run.expectGoldAccounted();

    expect(run.do(disconnectPlayer, { playerId: "c", tick: run.now }).ok).toBe(true);
    expect(buy("r8", "c", "rumor").rejection).toBe("player-disconnected");
    expect(run.do(quitPlayer, { playerId: "b", tick: run.now, position: { x: 0, y: 0 } }).ok).toBe(true);
    expect(buy("r9", "b", "rumor").rejection).toBe("player-left");
    expect(buy("r9", "ghost", "rumor").rejection).toBe("unknown-player");
    expect(buy("", "a", "rumor").rejection).toBe("invalid-request");
    expect(run.do(purchase, { requestId: "r9", playerId: "a", item: "scroll" as "rumor", tick: run.now }).rejection).toBe("invalid-request");
    expect(run.do(purchase, { requestId: "r9", playerId: "a", item: "rumor", tick: run.now - 1 }).rejection).toBe("stale-tick");
    // Only the decided refusals were kept, and none of them was charged.
    const refusals = run.state.requests.filter((outcome) => outcome.kind === "refusal");
    expect(refusals.map((outcome) => [outcome.playerId, outcome.requestId, outcome.rejection])).toEqual([
      ["a", "r2", "insufficient-gold"],
      ["a", "r4", "tonic-limit"],
      ["b", "r6", "player-in-duel"],
      ["c", "r8", "player-disconnected"],
    ]);
    expect(run.state.goldSpent).toBe(30 + 30 + 25 + 25);
    run.expectGoldAccounted();
  });

  it("answers a repeated request id with the original purchase, never charging twice, even after other operations", () => {
    const run = new Run("slice", ["a", "b"]);
    const original = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now });
    expect(original.ok).toBe(true);
    const settled = run.state;
    const retry = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now });
    expect(retry).toEqual({ ...original, replayed: true });
    expect(run.state).toBe(settled);

    // Other operations in between: a grant, another purchase, a used tonic and a lost duel.
    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "1", tick: ++run.now }).ok).toBe(true);
    expect(run.do(purchase, { requestId: "r2", playerId: "a", item: "rumor", tick: run.now }).ok).toBe(true);
    expect(run.do(useTonic, { playerId: "a", tick: run.now, atSea: true, grappled: false }).ok).toBe(true);
    run.duel("d1", "a", "b", "b");
    const [gold, tonics, spent] = [run.gold("a"), run.tonics("a"), run.state.goldSpent];

    const before = run.state;
    const late = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: ++run.now });
    expect(late).toEqual({ ...original, replayed: true });
    expect(run.state).toBe(before);
    // A retry carrying an old tick still finds its purchase rather than failing as stale.
    expect(run.do(purchase, { requestId: "r2", playerId: "a", item: "rumor", tick: 0 }).replayed).toBe(true);
    expect([run.gold("a"), run.tonics("a"), run.state.goldSpent]).toEqual([gold, tonics, spent]);
    // The same id reused by the same player for another item is refused, not replayed.
    expect(run.do(purchase, { requestId: "r1", playerId: "a", item: "rumor", tick: run.now }).rejection).toBe("duplicate");
    expect(run.state.requests.map((record) => record.requestId)).toEqual(["r1", "r2"]);
    run.expectGoldAccounted();
  });

  it("keys request ids per player: the same id from two players is two purchases, each replaying its own", () => {
    const run = new Run("slice", ["a", "b"]);
    const mine = run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now });
    const theirs = run.do(purchase, { requestId: "r1", playerId: "b", item: "rumor", tick: run.now });
    expect(mine).toMatchObject({ ok: true, replayed: false, purchase: { playerId: "a", item: "tonic" } });
    expect(theirs).toMatchObject({ ok: true, replayed: false, purchase: { playerId: "b", item: "rumor" } });
    expect([run.gold("a"), run.gold("b"), run.state.goldSpent]).toEqual([20, 25, 55]);
    const before = run.state;
    expect(run.do(purchase, { requestId: "r1", playerId: "b", item: "rumor", tick: run.now })).toEqual({ ...theirs, replayed: true });
    expect(run.do(purchase, { requestId: "r1", playerId: "a", item: "tonic", tick: run.now })).toEqual({ ...mine, replayed: true });
    // Another player's id never refuses nor reveals: b asking for a's item under "r1" still gets b's own answer.
    expect(run.do(purchase, { requestId: "r1", playerId: "b", item: "tonic", tick: run.now })).toMatchObject({ rejection: "duplicate", purchase: null });
    expect(run.state).toBe(before);
    run.expectGoldAccounted();
  });

  it("replays a decided refusal, even once it would succeed, and keeps nothing for a stale or unknown request", () => {
    const run = new Run("slice", ["a", "b"]);
    const buy = (requestId: string, playerId = "a", tick = run.now) => run.do(purchase, { requestId, playerId, item: "rumor", tick });
    expect(buy("r1").ok).toBe(true);
    expect(buy("r2").ok).toBe(false);
    const refused = run.state.requests.at(-1);
    expect(refused).toEqual({ kind: "refusal", requestId: "r2", playerId: "a", item: "rumor", tick: 1, rejection: "insufficient-gold" });
    expect([run.gold("a"), run.state.goldSpent]).toEqual([25, 25]);

    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "1", tick: ++run.now }).ok).toBe(true);
    const before = run.state;
    const retry = buy("r2");
    expect(retry).toEqual({ ok: false, rejection: "insufficient-gold", purchase: null, refusal: refused, replayed: true });
    expect(run.state).toBe(before);
    expect(buy("r2", "a", 0).refusal).toBe(refused);
    expect(run.state).toBe(before);
    expect(buy("r3")).toMatchObject({ ok: true, replayed: false, purchase: { requestId: "r3", goldAfter: 40 } });
    expect(run.state.goldSpent).toBe(50);

    // Stale, unknown-player and left-player requests are not decisions: the same state, and a later retry is fresh.
    const settled = run.state;
    expect(buy("r4", "a", run.now - 1).rejection).toBe("stale-tick");
    expect(buy("r4", "ghost").rejection).toBe("unknown-player");
    expect(run.do(purchase, { requestId: "r4", playerId: "a", item: "scroll" as "rumor", tick: run.now }).rejection).toBe("invalid-request");
    expect(run.state).toBe(settled);
    expect(buy("r4").ok).toBe(true);
    expect(run.do(quitPlayer, { playerId: "b", tick: run.now, position: { x: 0, y: 0 } }).ok).toBe(true);
    const gone = run.state;
    expect(buy("r1", "b").rejection).toBe("player-left");
    expect(run.state).toBe(gone);
    run.expectGoldAccounted();
  });

  it("keeps at most 16 refusals per player, evicting the oldest, whose id is then decided afresh", () => {
    const run = new Run("slice", ["a", "b"], 11, { ...objectiveRules, startingGold: 0 });
    const buy = (requestId: string, playerId = "a") => run.do(purchase, { requestId, playerId, item: "rumor", tick: run.now });
    expect(buy("x1", "b").rejection).toBe("insufficient-gold");
    for (let index = 1; index <= 16; index++) expect(buy(`x${index}`).rejection).toBe("insufficient-gold");
    const kept = () => run.state.requests.filter((outcome) => outcome.playerId === "a").map((outcome) => outcome.requestId);
    expect(kept()).toHaveLength(16);
    expect(buy("x17")).toMatchObject({ rejection: "insufficient-gold", replayed: false });
    expect(kept()).toEqual(Array.from({ length: 16 }, (_, index) => `x${index + 2}`));
    // b's refusal under the same id is b's own and stays.
    expect(buy("x1", "b")).toMatchObject({ rejection: "insufficient-gold", replayed: true });

    expect(run.do(grantGold, { playerId: "a", reason: "ruin", sourceKey: "0", tick: run.now }).ok).toBe(true);
    expect(buy("x2")).toMatchObject({ ok: false, rejection: "insufficient-gold", replayed: true });
    // The evicted id is evaluated fresh, and now succeeds.
    expect(buy("x1")).toMatchObject({ ok: true, replayed: false, purchase: { requestId: "x1", goldAfter: 15 } });
    expect(buy("x1")).toMatchObject({ ok: true, replayed: true });
    run.expectGoldAccounted();
  });
});

